def maxArea(mat):
    m, n = len(mat), len(mat[0])

    # dp[r][c] = side of the largest all-ones square whose bottom-right corner is (r, c)
    dp = [[0] * n for _ in range(m)]
    for r in range(m):
        for c in range(n):
            if mat[r][c] == 1:
                if r == 0 or c == 0:
                    dp[r][c] = 1
                else:
                    dp[r][c] = 1 + min(dp[r - 1][c], dp[r][c - 1], dp[r - 1][c - 1])

    # Can we place two disjoint k x k all-ones squares?
    def feasible(k):
        min_r = min_c = 10**9
        max_r = max_c = -1
        # Track the extreme bottom-right corners of all valid k x k squares
        for r in range(m):
            row = dp[r]
            for c in range(n):
                if row[c] >= k:
                    if r < min_r:
                        min_r = r
                    if r > max_r:
                        max_r = r
                    if c < min_c:
                        min_c = c
                    if c > max_c:
                        max_c = c
        if max_r < 0:
            return False
        # Two squares are disjoint iff they differ by at least k in rows or columns
        return max_r - min_r >= k or max_c - min_c >= k

    # Binary search for the largest feasible side length (feasibility is monotone)
    lo, hi = 0, min(m, n)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    return lo * lo
